/* =======================  字体导入部分 ======================== */

/* 1. 导入全局字体 "Cactus Classical Serif" (来自 ZeoSeven) */
@import url("https://fontsapi.zeoseven.com/318/main/result.css");

/* 2. 新增：使用 Google Fonts 替代私有字体 */
@import url('https://fonts.googleapis.com/css2?family=Satisfy&family=Great+Vibes&display=swap');

/* 全局字体设置 (应用到整个页面) */
body {
    font-family: "Cactus Classical Serif", sans-serif;
    font-weight: normal;
}

/* === 应用 Satisfy 到三元素 === */
.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay,
.mesIDDisplay::before,
.mesIDDisplay::after,
.mes_timer::before,
.mes_timer::after,
.tokenCounterDisplay::before,
.tokenCounterDisplay::after {
    font-family: 'Satisfy', cursive !important;
}

/* === 应用 Great Vibes 到思维链和按钮 === */
.mes_reasoning_header,
.mes_reasoning_header *,
.mes_reasoning_header_title::before,
.mes_edit::before,
.extraMesButtonsHint::before {
    font-family: 'Great Vibes', cursive !important;
}

/* 根变量 */
:root {
  --SmartThemeBodyColor: #21211c;
  --SmartThemeEmColor: #b3ab0f;
  --SmartThemeQuoteColor: #bbb31b;
  --SmartThemeUnderlineColor: #b6ae16;
  --SmartThemeBlurTintColor: rgba(248,248,246,0.85);
  --SmartThemeChatTintColor: rgba(244,243,241,0.3);
  --SmartThemeUserMesBlurTintColor: rgba(236,235,228,0.7);
  --SmartThemeBotMesBlurTintColor: rgba(242,241,238,0.2);
  --SmartThemeShadowColor: rgba(184,181,122,0.5);
  --SmartThemeBorderColor: rgba(0,0,0,0.1);
}

/* 文字颜色 */
#chat .mes .mes_text { color: #21211c !important; }
