html body #top-settings-holder { background: transparent !important; }
#send_form, body.no-blur #send_form { background-color: #f0efeb !important; }
.drawer-content:not(#charites_drawer_content) { background-color: #f1f1ee !important; color: #21211c !important; }

/* 思维链 */
.mes_reasoning_header_title { font-size: 0 !important; }
.mes_reasoning_header_title::before { content: "Rain"; font-size: 14px; color: #66655c; font-weight: normal; }

