/* ==================== 此处是消息文本基础样式部分 ==================== */
.mes_text {
    padding: 8px;
    margin: 0;
    font-family: "Cactus Classical Serif", serif;
    font-size: 14.7px;
    line-height: 1.6;
    color: #1a1a1a;
    background-color: transparent;
}

/* ==================== 段落 <p> 样式 ==================== */
.mes_text p {
    margin: 0 0 10px 0;
    color: #2c2c2c; /* 主要段落颜色 */
    font-weight: normal;
    text-align: left;
}

/* ==================== 引用 <q> 样式（不倾斜） ==================== */
.mes_text q {
    color: #bd2b2bb5; /* 您截图中的红色调 */
    font-style: normal; /* ← 关键：取消斜体 */
    border-left: 2px solid #e0e0e0;
    padding-left: 8px;
    margin: 0 0 10px 0;
    background: linear-gradient(
        to right,
        transparent 0%,
        rgba(189, 43, 43, 0.1) 20%,
        rgba(189, 43, 43, 0.1) 80%,
        transparent 100%
    );
    word-wrap: break-word;
}

/* ==================== 行内元素 <span> 样式 ==================== */
.mes_text span {
    color: #6188a7; /* 蓝绿色强调 */
    font-weight: normal;
    font-style: normal;
    background-color: transparent;
}

/* ==================== 删除线 <del> 样式 ==================== */
.mes_text del {
    color: #2c2c2c; /* 与段落一致 */
    text-decoration: line-through;
    text-decoration-color: #999;
    text-decoration-thickness: 2px;
    opacity: 0.7;
    font-weight: normal;
}

/* ==================== 代码块样式 ==================== */
.mes_text code, pre {
    font-family: "Cactus Classical Serif", serif;
    font-size: 14px;
    /* 使用 rgba 来设置背景颜色和透明度 */
    background-color: rgba(0, 0, 0, 0.8); /* 淡黑色背景，透明度为0.6 */
    color: rgba(220, 220, 220, 1); /* 浅色文字，确保对比度良好 */
    padding: 2px 4px;
    border-radius: 4px;
    border: none;
    margin: 0 2px;
}

/* ==================== 块级引用 <blockquote> ==================== */
.mes_text blockquote {
    background-color: rgba(240, 240, 240, 0.7);
    border-left: 4px solid #6188a7;
    padding: 12px 16px;
    margin: 12px 0;
    font-style: italic;
    color: #444;
    border-radius: 4px;
}
/* ==================== 此处是 edit more 修改部分 ==================== */
/* 1. 隐藏原始图标 */
.mes_button, .extraMesButtons .mes_button {
    filter: none !important;
    opacity: 0.7;
}

/* 2. 替换编辑按钮图标为文字 */
.mes_edit::before {
    content: 'Edit' !important;
    font-family: 'Great Vibes', cursive;
    font-size: 12px;
    color:  #B1B1A5;
    padding: 2px 8px;
    display: inline-block;
    line-height: 1;
}

/* 3. 替换“更多”按钮图标为文字 */
.extraMesButtonsHint::before {
    content: 'More' !important;
    font-family: 'Great Vibes', cursive;
    font-size: 12px;
    color:  #B1B1A5;
    padding: 2px 8px;
    display: inline-block;
    line-height: 1;
}
/* ==================== 此处是页数箭头修改部分 ==================== */
/* 1. 隐藏数字但保留布局 */
.swipes-counter {
    opacity: 0 !important;
    pointer-events: none;
}

/* 2. 统一左右箭头样式 */
.swipe_left::before,
.swipe_right::before {
    content: "" !important;
    font-family: "Cactus Classical Serif", sans-serif;
    font-size: 15px;
    line-height: 1;
    vertical-align: middle;
    display: inline-block;
    margin: 0;
    padding: 0;
}

.swipe_left::before {
    content: '⇤' !important;
    color: #999;
}

.swipe_right::before {
    content: '⇥' !important;
    color: #999;
}

/* 3. 确保箭头与文本对齐 */
.swipe_left,
.swipe_right {
    display: inline-block;
    vertical-align: middle;
    margin: 0 5px;
}
/* 在原有基础上添加下沉效果 */
.swipe_left,
.swipe_right {
    display: inline-block;
    vertical-align: middle;
    margin: 0 5px;
    transform: translateY(25px); /* 向下移动 2px，可调整 */
}


/* ==================== 此处是 qr 隐藏部分 ==================== */
/* ===== 感谢@qiyigeming老师的 qr隐藏 代码 有二改 ===== */

/* --- 默认隐藏 QR 按钮容器 --- */
.qr--buttons {
  opacity: 0 !important;
  visibility: hidden !important;
  max-height: 0 !important;
  transform: translateY(20px) !important;
  pointer-events: none !important;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.5s ease,
    transform 0.5s ease;
}

/* --- 输入框获得焦点时显示 QR 区域 --- */
#send_form:focus-within .qr--buttons {
  opacity: 1 !important;
  visibility: visible !important;
  max-height: 120px !important;
  transform: translateY(0) !important;
  pointer-events: auto !important;
}

/* --- 新增：修复空白弹窗，仅隐藏背景，不影响点击 --- */
#qr--bar {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.3s ease;
}

/* --- 当输入框聚焦或激活时才显示 QR bar 内容 --- */
#send_form:focus-within #qr--bar,
.qr--buttons.active #qr--bar {
  opacity: 1;
  visibility: visible;
  max-height: 200px;
  pointer-events: auto;
}
